int KiemtraSNT(int n) {
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return 0;
    return 1;
}
int TongSNT(int a[], int n) {
    int S = 0;
    for (int i = 0; i < n; i++)
        if (KiemtraSNT(a[i])) S += a[i];
    return S;
}

int TimMax(int a[], int n) {
    int m = 0;
    for (int i = 1; i < n; i++)
        if (a[i] > a[m]) m = i;
    return m;
}

